// Des: Tests car field normalizers on real listing texts
// Flo: text in > assert the number or code
// I/O: strings > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const norm = @import("pa-carz-norm.zig");
test "price: ty plus trieu, trieu only, decimal ty, grouped dong, installment tail" { try std.testing.expectEqual(@as(i64, 4_730_000_000), norm.normPric("- 4 Tỷ 730 Triệu")); try std.testing.expectEqual(@as(i64, 960_000_000), norm.normPric("960 triệu")); try std.testing.expectEqual(@as(i64, 2_700_000_000), norm.normPric("2.7 tỷ")); try std.testing.expectEqual(@as(i64, 1_399_000_000), norm.normPric("1 tỷ 399 triệu")); try std.testing.expectEqual(@as(i64, 1_030_000_000), norm.normPric("1.030.000.000 đ (Trả góp từ 11,5 triệu /tháng)")); try std.testing.expectEqual(@as(i64, 520_000_000), norm.normPric("520.000.000 đ")); try std.testing.expectEqual(@as(i64, 1_030_000_000), norm.normPric("1.030tr")); try std.testing.expectEqual(@as(i64, 1_500_000_000), norm.normPric("1,5 tỷ")); try std.testing.expectEqual(@as(i64, 639_000_000), norm.normPric("639 Triệu")); }
test "price: junk and small numbers are 0, never a crash" { const bads = [_][]const u8{ "", "Liên hệ", "Thỏa thuận", "12", "0", "tỷ", "abc triệu" }; for (bads) |badz| try std.testing.expectEqual(@as(i64, 0), norm.normPric(badz)); try std.testing.expectEqual(@as(i64, 0), norm.normPric("99999999999999999999 tỷ")); }
test "km: grouped, plain, vạn, suffix, none" { try std.testing.expectEqual(@as(i64, 84281), norm.normKmzz("84.281")); try std.testing.expectEqual(@as(i64, 11500), norm.normKmzz("11500")); try std.testing.expectEqual(@as(i64, 7000), norm.normKmzz("7.000 km")); try std.testing.expectEqual(@as(i64, 60000), norm.normKmzz("60,000KM")); try std.testing.expectEqual(@as(i64, 38000), norm.normKmzz("3,8 vạn km")); try std.testing.expectEqual(@as(i64, -1), norm.normKmzz("Xe mới")); try std.testing.expectEqual(@as(i64, -1), norm.normKmzz("")); try std.testing.expectEqual(@as(i64, 0), norm.normKmzz("0 km")); }
test "year: first plausible 4 digits, not inside a longer number" { try std.testing.expectEqual(@as(i64, 2022), norm.normYear("2022 ")); try std.testing.expectEqual(@as(i64, 2026), norm.normYear("Toyota Land Cruiser VX.R 3.5 V6 HEV 2026")); try std.testing.expectEqual(@as(i64, 0), norm.normYear("134891221")); try std.testing.expectEqual(@as(i64, 0), norm.normYear("1234")); try std.testing.expectEqual(@as(i64, 0), norm.normYear("")); }
test "gearbox codes" { try std.testing.expectEqualStrings("AT", norm.normGear("Số tự động")); try std.testing.expectEqualStrings("MT", norm.normGear("Số sàn")); try std.testing.expectEqualStrings("MT", norm.normGear("Số tay")); try std.testing.expectEqualStrings("CVT", norm.normGear("Hộp số CVT")); try std.testing.expectEqualStrings("AT", norm.normGear("1.5AT Luxury")); try std.testing.expectEqualStrings("", norm.normGear("Hạt")); try std.testing.expectEqualStrings("", norm.normGear("")); }
test "powertrain codes, PHEV before HEV before BEV" { try std.testing.expectEqualStrings("HEV", norm.normPowr("Hybrid 3.4 L")); try std.testing.expectEqualStrings("PHEV", norm.normPowr("Hybrid plug-in")); try std.testing.expectEqualStrings("MHEV", norm.normPowr("Mild hybrid")); try std.testing.expectEqualStrings("BEV", norm.normPowr("Điện")); try std.testing.expectEqualStrings("DSL", norm.normPowr("Dầu")); try std.testing.expectEqualStrings("GAS", norm.normPowr("Máy xăng")); try std.testing.expectEqualStrings("LPG", norm.normPowr("LPG")); try std.testing.expectEqualStrings("", norm.normPowr("Đang cập nhật")); }
test "condition codes" { try std.testing.expectEqualStrings("new", norm.normCond("Xe mới")); try std.testing.expectEqualStrings("used", norm.normCond("Đã sử dụng")); try std.testing.expectEqualStrings("used", norm.normCond("Xe cũ")); try std.testing.expectEqualStrings("", norm.normCond("")); }
test "phone digits: masked is not full, full is 9 to 11 digits" { var buff: [16]u8 = undefined; const mask = norm.normPhon("0922 079 ***", &buff); try std.testing.expect(!mask.full); try std.testing.expectEqualStrings("0922079", mask.digi); var buf2: [16]u8 = undefined; const full = norm.normPhon("0966.353.678", &buf2); try std.testing.expect(full.full); try std.testing.expectEqualStrings("0966353678", full.digi); var buf3: [16]u8 = undefined; try std.testing.expect(!norm.normPhon("", &buf3).full); try std.testing.expect(!norm.normPhon("12345", &buf3).full); }
